// ToolTip's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/tool_tip.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// How long the pointer rests on a target before its tooltip shows (ToolTipSettings::initial_delay); negative throws std::invalid_argument.
template <typename Declaring>
struct ToolTipInitialDelayCapability {
    PropertyView<std::chrono::milliseconds, ToolTipInitialDelayCapability<Declaring>> initial_delay;

    static void assign(ToolTipInitialDelayCapability& capability, std::chrono::milliseconds incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.initial_delay), std::move(incoming));
    }

    static std::chrono::milliseconds read(const ToolTipInitialDelayCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::chrono::milliseconds current = control.read_view(capability.initial_delay);
        return current;
    }
};

