// Every ToolTip capability, in the order the declaring class takes them.
template <typename Declaring>
struct ToolTipCapabilities : public ToolTipInitialDelayCapability<Declaring>,
                             public ToolTipReshowDelayCapability<Declaring>,
                             public ToolTipAutoPopDelayCapability<Declaring>,
                             public ToolTipShowOnHoverCapability<Declaring>,
                             public ToolTipShowOnFocusCapability<Declaring>,
                             public ToolTipShowAlwaysCapability<Declaring>,
                             public ToolTipMaximumWidthCapability<Declaring> {};

